from bisect import bisect_right

class Solution:

	def min_operations(self, nums):
		for i in range(len(nums)):
			nums[i] -= i
		lis = []
		for i in range(len(nums)):
			pos = bisect_right(lis, nums[i])
			if pos == len(lis):
				lis.append(nums[i])
			else:
				lis[pos] = nums[i]
		return len(nums) - len(lis)
